import { ChangeDetectionStrategy, Component, inject } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { FormBuilder, ReactiveFormsModule, Validators } from '@angular/forms';
import { map } from 'rxjs';
import { QuantityStepperComponent } from './quantity-stepper.component';

@Component({
  selector: 'app-root',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [ReactiveFormsModule, QuantityStepperComponent],
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent {
  private readonly fb = inject(FormBuilder);

  readonly form = this.fb.nonNullable.group({
    quantity: [2, [Validators.min(1), Validators.max(5)]]
  });
  readonly quantity = this.form.controls.quantity;

  // The control's own streams, read as signals so this OnPush view follows them.
  readonly value = toSignal(this.quantity.valueChanges, { initialValue: this.quantity.value });
  readonly status = toSignal(this.quantity.statusChanges, { initialValue: this.quantity.status });
  readonly touched = toSignal(this.quantity.events.pipe(map(() => this.quantity.touched)), {
    initialValue: this.quantity.touched
  });

  toggleDisabled(): void {
    if (this.quantity.disabled) {
      this.quantity.enable();
    } else {
      this.quantity.disable();
    }
  }

  reset(): void {
    // A non-nullable form resets to its starting value, 2.
    this.form.reset();
  }
}

