import { ChangeDetectionStrategy, Component, computed, forwardRef, input, signal } from '@angular/core';
import { ControlValueAccessor, NG_VALUE_ACCESSOR } from '@angular/forms';

@Component({
  selector: 'app-quantity-stepper',
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './quantity-stepper.component.html',
  styleUrls: ['./quantity-stepper.component.css'],
  providers: [
    // How formControlName finds this component: it registers as the control's value accessor.
    { provide: NG_VALUE_ACCESSOR, useExisting: forwardRef(() => QuantityStepperComponent), multi: true }
  ],
  host: { '(focusout)': 'markTouched()' }
})
export class QuantityStepperComponent implements ControlValueAccessor {
  readonly min = input(0);
  readonly max = input(99);
  readonly label = input('Quantity');

  protected readonly value = signal(0);
  protected readonly disabled = signal(false);
  protected readonly canDecrease = computed(() => !this.disabled() && this.value() > this.min());
  protected readonly canIncrease = computed(() => !this.disabled() && this.value() < this.max());

  private onChange: (value: number) => void = () => {};
  private onTouched: () => void = () => {};

  writeValue(value: number | null): void {
    // The form calls this from outside the template; a signal is what lets the OnPush view show it.
    this.value.set(value ?? this.min());
  }

  registerOnChange(fn: (value: number) => void): void {
    this.onChange = fn;
  }

  registerOnTouched(fn: () => void): void {
    this.onTouched = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    this.disabled.set(isDisabled);
  }

  step(delta: number): void {
    const next = Math.min(this.max(), Math.max(this.min(), this.value() + delta));
    if (next === this.value()) {
      return;
    }
    this.value.set(next);
    this.onChange(next);
  }

  markTouched(): void {
    this.onTouched();
  }
}

